function(value, { seriesIndex, dataPointIndex, w }) {
    const formatNumber = (number) => {
        return number.toLocaleString();
    };

    return [w.config.series[seriesIndex].name, formatNumber(value)];
}

tooltip.custom:
function({ series, seriesIndex, dataPointIndex, w }) {
  // ---------- helpers ----------
  const n = (v) => (v == null || v === '' ? null : Number(v));
  const formatNumber = (v) => (n(v) == null ? '' : n(v).toLocaleString());

  // Accept: number | string | bigint | { $ts:number|string|bigint } | { $:[ 'ts',*, ms ] }
  const coerceEpochMs = (ts) => {
    if (ts == null) return null;

    // plain number/string/bigint
    if (typeof ts === 'number' || typeof ts === 'string' || typeof ts === 'bigint') {
      const num = Number(ts);
      return isFinite(num) ? num : null;
    }

    // object with $ts
    if (typeof ts === 'object' && ts.hasOwnProperty('$ts')) {
      const num = Number(ts['$ts']);
      return isFinite(num) ? num : null;
    }

    // object with $ array: ["ts", zone, ms]
    if (typeof ts === 'object' && ts.hasOwnProperty('$') && Array.isArray(ts['$']) && ts['$'].length >= 3) {
      const num = Number(ts['$'][2]);
      return isFinite(num) ? num : null;
    }

    return null;
  };

  const formatDate = (ts) => {
    const ms = coerceEpochMs(ts);
    if (ms == null) return '—';
    const d = new Date(ms);
    if (isNaN(d.getTime())) return '—';
    return d.toLocaleString('en-US', {
      year: '2-digit', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', hour12: false
    }).replace(',', '');
  };

  // ---------- sources ----------
  const s = (w && w.config && w.config.series) ? (w.config.series[seriesIndex] || {}) : {};
  const dp = (s.data && s.data[dataPointIndex]) ? s.data[dataPointIndex] : {};
  const meta = dp.meta || {};

  const lotName = s.name || '';
  const qty = (series && series[seriesIndex]) ? series[seriesIndex][dataPointIndex] : dp.y;
  const asset = meta.assetPath || s.assetPath || '';
  const state = meta.lotStateName || s.lotStateName || '';
  const reason = meta.lotStateReasonName || s.lotStateReasonName || '';
  const item = meta.itemName || s.itemName || '';

  // <- the important bit: prefer meta.tStamp, then series tStamp
  const tsText = formatDate(meta.tStamp != null ? meta.tStamp : s.tStamp);

  return (
    "<div style='padding:5px'>" +
      "<b>Lot Name:</b> " + lotName + "<p>" +
      "<b>Qty:</b> " + formatNumber(qty) + "<p>" +
      "<b>Asset:</b> " + (asset || '') + "<p>" +
      "<b>State:</b> " + (state || '') + "<p>" +
      "<b>Reason:</b> " + (reason || '') + "<p>" +
      "<b>Item:</b> " + (item || '') + "<p>" +
    "</div>"
  );
}
